def _clean_sub_harnesses(names):
    clean, seen = [], set()
    for n in sorted(names):
        if "native" in n:
            continue
        base = n.replace("-sdk", "").replace("-code", "").replace("-build", "")
        if base in seen:
            continue
        seen.add(base)
        clean.append(n)
    return clean

